// Low-level CPython `str` semantics that JS does not provide out of the box.
// Everything here works on code points, the way Python does, instead of on
// UTF-16 code units.

/** Python's `len(s)`: number of code points, not UTF-16 units. */
export function codePointLen(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

/** Python's `list(s)` / iteration order: code points. */
export function codePoints(s) {
  return Array.from(s);
}

// Titlecase differs from uppercase for a handful of ligatures/digraphs, and
// `str.capitalize()` titlecases its first character (CPython >= 3.8).
const TITLECASE = new Map([
  ['ß', 'Ss'],   // ß
  ['Ǆ', 'ǅ'], ['ǅ', 'ǅ'], ['ǆ', 'ǅ'], // DŽ Dž dž
  ['Ǉ', 'ǈ'], ['ǈ', 'ǈ'], ['ǉ', 'ǈ'], // LJ Lj lj
  ['Ǌ', 'ǋ'], ['ǋ', 'ǋ'], ['ǌ', 'ǋ'], // NJ Nj nj
  ['Ǳ', 'ǲ'], ['ǲ', 'ǲ'], ['ǳ', 'ǲ'], // DZ Dz dz
  ['ﬀ', 'Ff'], ['ﬁ', 'Fi'], ['ﬂ', 'Fl'],
  ['ﬃ', 'Ffi'], ['ﬄ', 'Ffl'], ['ﬅ', 'St'], ['ﬆ', 'St'],
]);

/** Titlecase a single code point (Python's internal `to_title`). */
export function titleChar(ch) {
  const mapped = TITLECASE.get(ch);
  return mapped !== undefined ? mapped : ch.toUpperCase();
}

/** Python's `str.capitalize()`: titlecase the first code point, lower the rest. */
export function pyCapitalize(s) {
  if (s === '') return '';
  const first = String.fromCodePoint(s.codePointAt(0));
  return titleChar(first) + s.slice(first.length).toLowerCase();
}

/** Python's `str.lower()` / `str.upper()`. */
export function pyLower(s) {
  return s.toLowerCase();
}

export function pyUpper(s) {
  return s.toUpperCase();
}

/** Python's `str.title()`, needed by the case-matching helper in strutils. */
export function pyTitle(s) {
  let out = '';
  let previousIsCased = false;
  for (const ch of s) {
    const isCased = /\p{L}|\p{N}/u.test(ch) && /\p{Alphabetic}|\p{Nd}/u.test(ch);
    if (!previousIsCased) {
      out += isCased ? titleChar(ch) : ch;
    } else {
      out += ch.toLowerCase();
    }
    previousIsCased = isCased;
  }
  return out;
}

/** Python's `str.replace(old, new)`: replaces every occurrence. */
export function pyReplace(s, oldSub, newSub) {
  if (oldSub === '') return s;
  return s.split(oldSub).join(newSub);
}

