// Reimplementation of CPython's `repr()` / `print()` formatting for the value
// kinds this program prints: str, int, list and dict (plus objects that expose
// their own `__repr__()`).

// `str.isprintable()`: everything in the "Other" (C*) and "Separator" (Z*)
// general categories is non-printable, except the ASCII space.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zs}\p{Zl}\p{Zp}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function escapeCodePoint(ch) {
  const cp = ch.codePointAt(0);
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/** CPython's `repr()` for `str`. */
export function reprStr(s) {
  // Python prefers single quotes, switching to double quotes only when the
  // string contains a single quote but no double quote.
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (isPrintable(ch)) out += ch;
    else out += escapeCodePoint(ch);
  }
  return out + quote;
}

/** CPython's `repr()` for `int` / `float`. */
export function reprNumber(n) {
  if (Number.isInteger(n)) return String(n);
  if (Number.isNaN(n)) return 'nan';
  if (n === Infinity) return 'inf';
  if (n === -Infinity) return '-inf';
  return String(n);
}

/** CPython's `repr()`, dispatching on value kind. */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'number') return reprNumber(value);
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  if (typeof value.__repr__ === 'function') return value.__repr__();
  if (value instanceof Map) return reprDict(value);
  return String(value);
}

/** CPython's `repr()` for `dict`, backed by a Map to keep insertion order. */
export function reprDict(map) {
  const items = [];
  for (const [k, v] of map) items.push(`${pyRepr(k)}: ${pyRepr(v)}`);
  return '{' + items.join(', ') + '}';
}

/** CPython's `str()`: strings pass through unquoted, everything else is repr'd. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

/** CPython's `print(value)` for a single argument. */
export function pyPrint(value) {
  process.stdout.write(pyStr(value) + '\n');
}

