// Reimplementation of the `boltons.dictutils` pieces used here: an immutable
// mapping that keeps insertion order and reprs as `FrozenDict({...})`.

import { reprDict } from './pyrepr.mjs';

/**
 * A Python `dict` stand-in: a Map keeps insertion order and last-write-wins
 * value semantics for duplicate keys, exactly like a dict comprehension.
 */
export function pyDict(entries = []) {
  const map = new Map();
  for (const [k, v] of entries) map.set(k, v);
  return map;
}

/** Python's `zip(a, b)`, truncating to the shorter sequence. */
export function zip(a, b) {
  const pairs = [];
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) pairs.push([a[i], b[i]]);
  return pairs;
}

/** An immutable dict. Mutating methods are absent; the instance is frozen. */
export class FrozenDict {
  constructor(source = []) {
    const entries = source instanceof Map
      ? source.entries()
      : (source instanceof FrozenDict ? source.entries() : source);
    const map = new Map();
    for (const [k, v] of entries) map.set(k, v);
    Object.defineProperty(this, '_map', { value: map, enumerable: false });
    Object.freeze(this);
  }

  get(key, fallback = undefined) {
    return this._map.has(key) ? this._map.get(key) : fallback;
  }

  has(key) {
    return this._map.has(key);
  }

  get size() {
    return this._map.size;
  }

  keys() {
    return this._map.keys();
  }

  values() {
    return this._map.values();
  }

  entries() {
    return this._map.entries();
  }

  [Symbol.iterator]() {
    return this._map.keys();
  }

  __repr__() {
    return `FrozenDict(${reprDict(this._map)})`;
  }

  toString() {
    return this.__repr__();
  }
}

