// A minimal stand-in for Python's `argparse.ArgumentParser`, covering the
// subset this program needs: long options with a single value, `-h/--help`,
// required-argument checking, and argparse's exact usage/help/error wording.

import path from 'node:path';

// argparse treats a lone `-1` / `-1.5` as a value, not as an option, when no
// option string itself starts with a digit.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

const MAX_HELP_POSITION = 24;
const INDENT = '  ';

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog !== undefined ? prog : path.basename(process.argv[1] || 'program');
    this.actions = [
      {
        optionStrings: ['-h', '--help'],
        dest: 'help',
        isHelp: true,
        required: false,
        help: 'show this help message and exit',
      },
    ];
  }

  addArgument(optionStrings, { dest, required = false, help = '', metavar } = {}) {
    const flags = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const inferredDest = dest || flags[0].replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push({
      optionStrings: flags,
      dest: inferredDest,
      isHelp: false,
      required,
      help,
      metavar: metavar || inferredDest.toUpperCase(),
    });
    return this;
  }

  /** The invocation shown in the options list, e.g. `-h, --help` or `--a A`. */
  _formatInvocation(action) {
    if (action.isHelp) return action.optionStrings.join(', ');
    return action.optionStrings.map((f) => `${f} ${action.metavar}`).join(', ');
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const body = action.isHelp
        ? action.optionStrings[0]
        : `${action.optionStrings[0]} ${action.metavar}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  formatHelp() {
    const invocations = this.actions.map((a) => this._formatInvocation(a));
    const actionMaxLength = Math.max(...invocations.map((i) => i.length)) + INDENT.length;
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    const lines = [this.formatUsage(), '', 'options:'];
    this.actions.forEach((action, i) => {
      const head = INDENT + invocations[i];
      if (!action.help) {
        lines.push(head);
      } else if (head.length < helpPosition) {
        lines.push(head + ' '.repeat(helpPosition - head.length) + action.help);
      } else {
        lines.push(head);
        lines.push(' '.repeat(helpPosition) + action.help);
      }
    });
    return lines.join('\n') + '\n';
  }

  exitWithHelp() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _knownOptionStrings() {
    const known = new Set();
    for (const action of this.actions) {
      for (const flag of action.optionStrings) known.add(flag);
    }
    return known;
  }

  /** argparse's `_parse_optional`: does this token look like an option? */
  _looksLikeOption(token) {
    if (token === '') return false;
    if (token[0] !== '-') return false;
    if (this._knownOptionStrings().has(token)) return true;
    if (token.length === 1) return false;
    if (token.includes('=') && this._knownOptionStrings().has(token.split('=')[0])) return true;
    if (NEGATIVE_NUMBER_RE.test(token)) return false;
    if (token.includes(' ')) return false;
    return true;
  }

  /** Resolve a long option, allowing unambiguous abbreviations. */
  _matchLongOption(name) {
    const exact = this.actions.find((a) => a.optionStrings.includes(name));
    if (exact) return { action: exact, ambiguous: [] };
    const prefixed = this.actions.filter((a) =>
      a.optionStrings.some((f) => f.startsWith('--') && f.startsWith(name)));
    if (prefixed.length === 1) return { action: prefixed[0], ambiguous: [] };
    return { action: null, ambiguous: prefixed };
  }

  parseArgs(argv) {
    const values = {};
    const seen = new Set();
    const extras = [];
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (onlyPositionals) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        onlyPositionals = true;
        continue;
      }
      if (!this._looksLikeOption(token)) {
        extras.push(token);
        continue;
      }

      let name = token;
      let explicitValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        explicitValue = token.slice(eq + 1);
      }

      const { action } = this._matchLongOption(name);
      if (!action) {
        // Unknown options become "unrecognized arguments", as in
        // parse_known_args, together with any value that followed them.
        extras.push(token);
        continue;
      }
      if (action.isHelp) {
        this.exitWithHelp();
      }

      if (explicitValue !== null) {
        values[action.dest] = explicitValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || this._looksLikeOption(next)) {
          this.error(`argument ${name}: expected one argument`);
        }
        values[action.dest] = next;
        i++;
      }
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.optionStrings.join('/'));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

