// Reimplementation of the `boltons.strutils` helpers used by this program,
// derived from observed interface behaviour: camel2under, under2camel,
// slugify, split_punct_ws, unit_len, cardinalize and pluralize.

import { pyCapitalize, pyTitle, codePointLen } from './pystr.mjs';

// A capital letter that follows a lowercase letter/digit, or that starts a new
// capitalized word inside the string (but never at position 0).
const CAMEL2UNDER_RE = /((?<=[a-z0-9])[A-Z]|(?!^)[A-Z](?=[a-z]))/g;

/**
 * camel2under('addressLine1') -> 'address_line1'
 * Insert an underscore before every word-starting capital, then lowercase.
 */
export function camel2under(camelString) {
  return camelString.replace(CAMEL2UNDER_RE, '_$1').toLowerCase();
}

/**
 * under2camel('complex_tokenizer') -> 'ComplexTokenizer'
 * Every underscore-delimited chunk is capitalized; an empty chunk (i.e. a
 * doubled/leading/trailing underscore) contributes a literal underscore.
 */
export function under2camel(string) {
  return string
    .split('_')
    .map((w) => pyCapitalize(w) || '_')
    .join('');
}

// string.punctuation + string.whitespace, as an explicit set so no regex
// escaping subtleties can creep in. These are ASCII-only: non-ASCII
// punctuation and non-ASCII spaces are *not* separators.
const PUNCT_WS = new Set([
  ...'!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~',
  ' ', '\t', '\n', '\r', '\v', '\f',
]);

/**
 * split_punct_ws('First post! Hi!!!!~1    ') -> ['First', 'post', 'Hi', '1']
 * Splits on runs of punctuation/whitespace, dropping empty chunks.
 */
export function splitPunctWs(text) {
  const parts = [];
  let current = '';
  for (const ch of text) {
    if (PUNCT_WS.has(ch)) {
      if (current !== '') {
        parts.push(current);
        current = '';
      }
    } else {
      current += ch;
    }
  }
  if (current !== '') parts.push(current);
  return parts;
}

/**
 * slugify('Test String!') -> 'test_string'
 * Non-empty input that is entirely punctuation/whitespace collapses to a bare
 * delimiter; empty input stays empty.
 */
export function slugify(text, delim = '_', lower = true) {
  const parts = splitPunctWs(text);
  let ret = parts.join(delim);
  if (ret === '' && text !== '') ret = delim;
  if (lower) ret = ret.toLowerCase();
  return ret;
}

// Irregular singular -> plural forms, kept small on purpose: only the nouns a
// caller actually passes in matter.
const IRR_S2P = new Map([
  ['addendum', 'addenda'], ['alga', 'algae'], ['alumna', 'alumnae'],
  ['alumnus', 'alumni'], ['analysis', 'analyses'], ['antenna', 'antennae'],
  ['appendix', 'appendices'], ['axis', 'axes'], ['bacillus', 'bacilli'],
  ['bacterium', 'bacteria'], ['basis', 'bases'], ['beau', 'beaux'],
  ['child', 'children'], ['crisis', 'crises'], ['criterion', 'criteria'],
  ['curriculum', 'curricula'], ['datum', 'data'], ['deer', 'deer'],
  ['diagnosis', 'diagnoses'], ['ellipsis', 'ellipses'], ['fish', 'fish'],
  ['focus', 'foci'], ['foot', 'feet'], ['formula', 'formulae'],
  ['fungus', 'fungi'], ['genus', 'genera'], ['goose', 'geese'],
  ['hypothesis', 'hypotheses'], ['index', 'indices'], ['louse', 'lice'],
  ['man', 'men'], ['matrix', 'matrices'], ['means', 'means'],
  ['medium', 'media'], ['memorandum', 'memoranda'], ['mouse', 'mice'],
  ['nebula', 'nebulae'], ['nucleus', 'nuclei'], ['oasis', 'oases'],
  ['offspring', 'offspring'], ['ovum', 'ova'], ['ox', 'oxen'],
  ['paralysis', 'paralyses'], ['parenthesis', 'parentheses'],
  ['person', 'people'], ['phenomenon', 'phenomena'], ['radius', 'radii'],
  ['series', 'series'], ['sheep', 'sheep'], ['species', 'species'],
  ['stimulus', 'stimuli'], ['stratum', 'strata'], ['tableau', 'tableaux'],
  ['thesis', 'theses'], ['tooth', 'teeth'], ['vertebra', 'vertebrae'],
  ['vita', 'vitae'], ['woman', 'women'],
]);

const VOWELS = new Set(['a', 'e', 'i', 'o', 'u']);

/** Copy the casing pattern of *master* onto *disciple*. */
function matchCase(master, disciple) {
  if (master.trim() === '') return disciple;
  if (master.toLowerCase() === master) return disciple.toLowerCase();
  if (master.toUpperCase() === master) return disciple.toUpperCase();
  if (pyTitle(master) === master) return pyTitle(disciple);
  return disciple;
}

/**
 * pluralize('friend') -> 'friends'; pluralize('enemy') -> 'enemies'
 * Semi-intelligent singular -> plural, preserving the input's case pattern.
 */
export function pluralize(word) {
  const origWord = word;
  const lowered = word.trim().toLowerCase();
  if (lowered === '') return origWord;

  const irregular = IRR_S2P.get(lowered);
  if (irregular !== undefined) return matchCase(origWord, irregular);

  let plural;
  if (
    lowered.endsWith('s') || lowered.endsWith('x') || lowered.endsWith('z') ||
    lowered.endsWith('ch') || lowered.endsWith('sh')
  ) {
    plural = lowered + 'es';
  } else if (lowered.endsWith('y') && !VOWELS.has(lowered.slice(-2, -1))) {
    plural = lowered.slice(0, -1) + 'ies';
  } else {
    plural = lowered + 's';
  }
  return matchCase(origWord, plural);
}

/** Pluralize *unitNoun* unless *count* is exactly one. */
export function cardinalize(unitNoun, count) {
  if (count === 1) return unitNoun;
  return pluralize(unitNoun);
}

/**
 * unit_len(['a', 'b'], 'string') -> '2 strings'
 * A plain-English description of a sized iterable's length.
 */
export function unitLen(sizedIterable, unitNoun = 'item') {
  const count = typeof sizedIterable === 'string'
    ? codePointLen(sizedIterable)
    : sizedIterable.length;
  const units = cardinalize(unitNoun, count);
  if (count) return `${count} ${units}`;
  return `No ${units}`;
}

